package com.mytimelogger.app;

import android.content.ContentResolver;
import android.content.res.AssetFileDescriptor;
import android.net.Uri;
import java.io.*;
import java.net.*;
import com.google.gson.*;

final class SleepAutomationApiClient {
    static final long MAX=15L*1024L*1024L; private final ContentResolver resolver;
    static final class Result { final String code,body; Result(String c,String b){code=c;body=b;} }
    static final class Job { final String state,requestId; final boolean reportReady; Job(String s,String id){this(s,id,false);} Job(String s,String id,boolean ready){state=s;requestId=id;reportReady=ready;} }
    SleepAutomationApiClient(ContentResolver resolver){this.resolver=resolver;}
    static String endpoint(String base,String date)throws Exception{return endpoint(base,date,true);}
    static String endpoint(String base,String date,boolean analyze)throws Exception{return base.replaceAll("/+$","")+"/upload?analyze="+analyze+"&full=false&force=false&date="+URLEncoder.encode(date,"UTF-8");}
    static String classify(int status){if(status==401)return "unauthorized";if(status>=500)return "server_error";return status>=200&&status<300?"ok":"http_error";}
    static boolean tooLarge(long size){return size>MAX;}
    static Job uploadJob(Result result){try{if(!"ok".equals(result.code))return new Job(result.code,"");JsonObject j=JsonParser.parseString(result.body).getAsJsonObject();String id=j.get("request_id").getAsString();return new Job(j.has("reused")&&j.get("reused").getAsBoolean()?"reused":"queued",id);}catch(Exception e){return new Job("protocol_error","");}}
    static Job statusJob(Result result,String expectedDate){try{if(!"ok".equals(result.code))return new Job(result.code,"");JsonObject j=JsonParser.parseString(result.body).getAsJsonObject();String state=j.get("status").getAsString(),date=j.has("date")&&!j.get("date").isJsonNull()?j.get("date").getAsString():"";if(!date.isEmpty()&&!expectedDate.equals(date))return new Job("date_mismatch","");if(!java.util.Arrays.asList("queued","running","uploaded","done","reused","error").contains(state))return new Job("protocol_error","");JsonObject data=j.has("result")&&j.get("result").isJsonObject()?j.getAsJsonObject("result"):new JsonObject();boolean ready=sleepReportReady(data);if("error".equals(state)&&!ready)return new Job(reportError(j),j.get("request_id").getAsString());return new Job(state,j.get("request_id").getAsString(),ready);}catch(Exception e){return new Job("protocol_error","");}}
    static boolean sleepReportReady(JsonObject data){try{return data.has("report_status")&&data.get("report_status").getAsInt()>=1&&((data.has("analysis_report")&&!data.get("analysis_report").getAsString().trim().isEmpty())||(data.has("analysis_html")&&!data.get("analysis_html").getAsString().trim().isEmpty()));}catch(Exception e){return false;}}
    static String dateReportState(Result result,String expectedDate){try{if(!"ok".equals(result.code)){return "http_error".equals(result.code)&&result.body.contains("date not found")?"missing":"unknown";}JsonObject j=JsonParser.parseString(result.body).getAsJsonObject();String date=j.has("date")?j.get("date").getAsString():"";if(!expectedDate.equals(date))return "unknown";JsonObject data=j.has("result")&&j.get("result").isJsonObject()?j.getAsJsonObject("result"):new JsonObject();if(sleepReportReady(data))return "ready";String state=j.has("status")?j.get("status").getAsString():"";return java.util.Arrays.asList("queued","running","done","reused","error").contains(state)?"missing":"unknown";}catch(Exception e){return "unknown";}}
    static String reportError(JsonObject job){String raw=job.has("error")&&!job.get("error").isJsonNull()?job.get("error").getAsString().toLowerCase(java.util.Locale.ROOT):"";if(raw.contains("未配置视觉大模型")||raw.contains("vision model"))return "vision_model_unconfigured";if(raw.contains("ocr")||raw.contains("识别"))return "ocr_failed";if(raw.contains("apistatuserror")||raw.contains("模型"))return "model_provider_error";return "report_failed";}
    static String statusEndpoint(String base,String id)throws Exception{return base.replaceAll("/+$","")+"/status/"+URLEncoder.encode(id,"UTF-8");}
    static String statusByDateEndpoint(String base,String date)throws Exception{return base.replaceAll("/+$","")+"/status_by_date/"+URLEncoder.encode(date,"UTF-8");}
    static String retryEndpoint(String base)throws Exception{return base.replaceAll("/+$","")+"/generate_report";}

    Result upload(String uri,String date,String base,String token){return upload(uri,date,base,token,true);}
    Result upload(String uri,String date,String base,String token,boolean analyze){HttpURLConnection c=null;
        try(AssetFileDescriptor fd=resolver.openAssetFileDescriptor(Uri.parse(uri),"r")){if(fd!=null&&tooLarge(fd.getLength()))return new Result("too_large","");
            String boundary="MTLSleepBoundary";c=(HttpURLConnection)new URL(endpoint(base,date,analyze)).openConnection();c.setConnectTimeout(30000);c.setReadTimeout(30000);c.setDoOutput(true);c.setRequestMethod("POST");c.setRequestProperty("Authorization","Bearer "+token);c.setRequestProperty("Content-Type","multipart/form-data; boundary="+boundary);c.setChunkedStreamingMode(8192);
            try(OutputStream out=c.getOutputStream();InputStream in=resolver.openInputStream(Uri.parse(uri))){out.write(("--"+boundary+"\r\nContent-Disposition: form-data; name=\"file\"; filename=\"sleep.jpg\"\r\nContent-Type: image/jpeg\r\n\r\n").getBytes("UTF-8"));byte[] buf=new byte[8192];long total=0;for(int n;(n=in.read(buf))>=0;){total+=n;if(tooLarge(total))return new Result("too_large","");out.write(buf,0,n);}out.write(("\r\n--"+boundary+"--\r\n").getBytes("UTF-8"));}
            int status=c.getResponseCode();return new Result(classify(status),read(status<400?c.getInputStream():c.getErrorStream()));
        }catch(SocketTimeoutException e){return new Result("timeout","");}catch(Exception e){return new Result("network_error","");}finally{if(c!=null)c.disconnect();}}
    Result status(String id,String date,String base,String token){HttpURLConnection c=null;try{c=(HttpURLConnection)new URL(statusEndpoint(base,id)).openConnection();c.setConnectTimeout(30000);c.setReadTimeout(30000);c.setRequestProperty("Authorization","Bearer "+token);int status=c.getResponseCode();return new Result(classify(status),read(status<400?c.getInputStream():c.getErrorStream()));}catch(SocketTimeoutException e){return new Result("timeout","");}catch(Exception e){return new Result("network_error","");}finally{if(c!=null)c.disconnect();}}
    Result statusByDate(String date,String base,String token){HttpURLConnection c=null;try{c=(HttpURLConnection)new URL(statusByDateEndpoint(base,date)).openConnection();c.setConnectTimeout(8000);c.setReadTimeout(8000);c.setRequestProperty("Authorization","Bearer "+token);int status=c.getResponseCode();return new Result(classify(status),read(status<400?c.getInputStream():c.getErrorStream()));}catch(SocketTimeoutException e){return new Result("timeout","");}catch(Exception e){return new Result("network_error","");}finally{if(c!=null)c.disconnect();}}
    Result retryReport(String date,String base,String token){return report(date,base,token,true);}
    Result quickReport(String date,String base,String token){return report(date,base,token,false);}
    private Result report(String date,String base,String token,boolean full){HttpURLConnection c=null;try{c=(HttpURLConnection)new URL(retryEndpoint(base)).openConnection();c.setConnectTimeout(30000);c.setReadTimeout(30000);c.setDoOutput(true);c.setRequestMethod("POST");c.setRequestProperty("Authorization","Bearer "+token);c.setRequestProperty("Content-Type","application/json; charset=utf-8");JsonObject payload=new JsonObject();payload.addProperty("date",date);payload.addProperty("full",full);payload.addProperty("force",false);try(OutputStream out=c.getOutputStream()){out.write(payload.toString().getBytes("UTF-8"));}int status=c.getResponseCode();return new Result(classify(status),read(status<400?c.getInputStream():c.getErrorStream()));}catch(SocketTimeoutException e){return new Result("timeout","");}catch(Exception e){return new Result("network_error","");}finally{if(c!=null)c.disconnect();}}
    private static String read(InputStream in)throws Exception{if(in==null)return "";try(InputStream source=in;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[2048];for(int n;(n=source.read(b))>=0;)out.write(b,0,n);return out.toString("UTF-8");}}
}
